-- Catálogo original transcrito desde el menú de Cochi y recursos incluidos en el ZIP.
-- Ejecutar después de schema.sql. Los valores conflictivos por slug se actualizan.
on conflict (slug) do update set
  id=excluded.id, name=excluded.name, category=excluded.category, description=excluded.description, price_usd=excluded.price_usd, image=excluded.image, available=excluded.available, availability_days=excluded.availability_days, is_visible=excluded.is_visible, is_coming_soon=excluded.is_coming_soon, featured=excluded.featured, brand=excluded.brand, sort_order=excluded.sort_order, options=excluded.options, updated_at=now();